function SpaceEditor({draftValue,addExpert,initial,mode,projects,employees,close,save,addProject}:{draftValue?:SpaceValue;addExpert?(value:SpaceValue):void;initial?:Space;mode:'create'|'details'|'projects'|'team';projects:Project[];employees:Employee[];close():void;save(value:SpaceValue):Promise<void>;addProject():void}){
 const L=useCopy(),confirm=useConfirm();const [original]=useState<SpaceValue>(initial||{name:'',purpose:'',projectIds:[],members:[]}),[value,setValue]=useState(draftValue||original),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 const leave=async(after?:()=>void)=>{if(busy)return;if(JSON.stringify(value)!==JSON.stringify(original)&&!await confirm({title:L('放弃未保存的修改？','Discard unsaved edits?'),description:L('空间修改尚未保存。','Your space changes have not been saved.'),action:L('放弃修改','Discard')}))return;close();after?.();};
 return <Dialog open onOpenChange={open=>!open&&void leave()}><DialogContent className="wf-dialog sm:max-w-[720px] p-6 flex"><DialogHeader><DialogTitle>{({create:L('创建项目空间','Create project space'),details:L('编辑空间目标','Edit space goal'),projects:L('管理关联项目','Manage linked projects'),team:L('空间成员与分工','Space members and assignments')}[mode])}</DialogTitle><DialogDescription>{L('空间是逻辑关联，不会移动或复制项目目录，也不会自动开始工作。','A space creates logical links without moving or copying directories or starting work.')}</DialogDescription></DialogHeader><Failure message={error}/><div className="wf-picker-scroll"><FieldGroup>{['create','details'].includes(mode)&&<><FormField label={L('空间名称','Space name')} value={value.name} onChange={name=>setValue(v=>({...v,name}))} maxLength={100} required placeholder="AI Coding"/><FormField label={L('共同目标（可选）','Shared goal (optional)')} value={value.purpose} onChange={purpose=>setValue(v=>({...v,purpose}))} multiline maxLength={4000}/></>}
 {mode==='projects'&&<FieldSet><FieldLegend>{L('已有项目','Existing projects')}</FieldLegend>{projects.map(p=><label className="wf-check" key={p.id}><Checkbox checked={value.projectIds.includes(p.id)} onCheckedChange={checked=>setValue(v=>({...v,projectIds:checked?[...v.projectIds,p.id]:v.projectIds.filter(id=>id!==p.id),members:v.members.map(m=>({...m,projectIds:m.projectIds.filter(id=>checked||id!==p.id)}))}))}/><span>{p.name} · {environment(p)}<small>{p.path}</small></span></label>)}<Button variant="outline" disabled={busy} onClick={()=>void leave(addProject)}>{L('登记其他项目','Register another project')}</Button><FieldDescription>{L('解除关联不会删除项目；本地、SSH 和容器位置由原项目维护。','Unlinking keeps the project. Local, SSH and container settings stay with the original project.')}</FieldDescription></FieldSet>}
 {mode==='team'&&<WorkforceMemberPicker employees={employees} projects={projects} value={value} change={setValue} disabled={busy} addExpert={addExpert?()=>addExpert(value):undefined}/>}
 {mode==='create'&&<FieldDescription role="note" className="flex items-start gap-2"><Info aria-hidden="true" className="mt-0.5 size-4 shrink-0"/><span>{L('创建后再逐步关联项目、选择专家和分配职责。无需指定空间目录。','After creation, link projects and assign experts step by step. No space directory is required.')}</span></FieldDescription>}</FieldGroup></div><DialogFooter><Button variant="outline" disabled={busy} onClick={()=>void leave()}>{L('取消','Cancel')}</Button><Button disabled={busy||!value.name.trim()} onClick={()=>void(async()=>{setBusy(true);setError('');try{await save(value);}catch(e){setError((e as Error).message);}finally{setBusy(false);}})()}>{L('保存空间','Save space')}</Button></DialogFooter></DialogContent></Dialog>;
}
